messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Walk-Run Cycle</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #1a1d24; }
  #c { display: block; width: 100%; height: 100%; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script type="module">
import * as THREE from './three.module.js';

const canvas = document.getElementById('c');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1d24);
scene.fog = new THREE.Fog(0x1a1d24, 14, 30);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.6, 7.5);
camera.lookAt(0, 1.0, 0);

// Lighting
scene.add(new THREE.HemisphereLight(0x8899bb, 0x332e28, 0.9));
const sun = new THREE.DirectionalLight(0xfff2dd, 1.6);
sun.position.set(4, 8, 5);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -6; sun.shadow.camera.right = 6;
sun.shadow.camera.top = 6; sun.shadow.camera.bottom = -6;
scene.add(sun);

// ---- Treadmill-style ground ----
const ground = new THREE.Mesh(
  new THREE.BoxGeometry(4.2, 0.3, 10),
  new THREE.MeshStandardMaterial({ color: 0x2c2f38, roughness: 0.85 })
);
ground.position.y = -0.15;
ground.receiveShadow = true;
scene.add(ground);

const beltMat = new THREE.MeshStandardMaterial({ color: 0x1f2229, roughness: 0.95 });
const belt = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.06, 9), beltMat);
belt.position.y = 0.03;
belt.receiveShadow = true;
scene.add(belt);

// moving belt stripes to imply treadmill motion
const stripeMat = new THREE.MeshStandardMaterial({ color: 0x3a3f4c, roughness: 0.9 });
const stripes = [];
for (let i = 0; i < 14; i++) {
  const s = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.02, 0.14), stripeMat);
  s.position.set(0, 0.07, -4.5 + i * 0.7);
  scene.add(s);
  stripes.push(s);
}

// side rails
const railMat = new THREE.MeshStandardMaterial({ color: 0x556077, roughness: 0.5, metalness: 0.3 });
[-1.25, 1.25].forEach(x => {
  const rail = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 9), railMat);
  rail.position.set(x, 0.35, 0);
  rail.castShadow = true;
  scene.add(rail);
});

// ---- Low-poly humanoid ----
const skin = new THREE.MeshStandardMaterial({ color: 0xd98f6b, roughness: 0.8, flatShading: true });
const shirt = new THREE.MeshStandardMaterial({ color: 0x3f7fae, roughness: 0.8, flatShading: true });
const pants = new THREE.MeshStandardMaterial({ color: 0x37404e, roughness: 0.85, flatShading: true });
const shoe = new THREE.MeshStandardMaterial({ color: 0x22252c, roughness: 0.9, flatShading: true });

function limbMesh(w, h, d, mat, py) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.geometry.translate(0, py, 0);
  m.castShadow = true;
  return m;
}

const figure = new THREE.Group();
scene.add(figure);

// torso (pivot at hips, y ~ 1.0)
const torso = new THREE.Group();
torso.position.y = 1.0;
figure.add(torso);

const chest = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.62, 0.28), shirt);
chest.geometry.translate(0, 0.31, 0);
chest.castShadow = true;
torso.add(chest);

const hips = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.2, 0.26), pants);
hips.geometry.translate(0, -0.1, 0);
hips.castShadow = true;
torso.add(hips);

// head
const neck = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.1, 0.12), skin);
neck.geometry.translate(0, 0.05, 0);
torso.add(neck);

const headPivot = new THREE.Group();
headPivot.position.y = 0.68;
torso.add(headPivot);

const head = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.32, 0.3), skin);
head.geometry.translate(0, 0.16, 0);
head.castShadow = true;
headPivot.add(head);

const hair = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.1, 0.32), new THREE.MeshStandardMaterial({ color: 0x3a2a20, roughness: 1, flatShading: true }));
hair.geometry.translate(0, 0.3, 0);
headPivot.add(hair);

// Arms: shoulder pivots at torso-local (±0.31, 0.52, 0)
function makeArm(side) {
  const pivot = new THREE.Group();
  pivot.position.set(0.31 * side, 0.52, 0);
  const upper = limbMesh(0.13, 0.3, 0.13, shirt, -0.15);
  pivot.add(upper);
  const elbow = new THREE.Group();
  elbow.position.y = -0.3;
  pivot.add(elbow);
  const fore = limbMesh(0.11, 0.28, 0.11, skin, -0.14);
  elbow.add(fore);
  const hand = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.1, 0.12), skin);
  hand.geometry.translate(0, -0.33, 0);
  hand.castShadow = true;
  elbow.add(hand);
  torso.add(pivot);
  return { pivot, elbow };
}
const armL = makeArm(1);
const armR = makeArm(-1);

// Legs: hip pivots at figure-local (±0.12, 1.0, 0)
function makeLeg(side) {
  const pivot = new THREE.Group();
  pivot.position.set(0.12 * side, 1.0, 0);
  const thigh = limbMesh(0.16, 0.42, 0.16, pants, -0.21);
  pivot.add(thigh);
  const knee = new THREE.Group();
  knee.position.y = -0.42;
  pivot.add(knee);
  const shin = limbMesh(0.14, 0.4, 0.14, pants, -0.2);
  knee.add(shin);
  const foot = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.09, 0.28), shoe);
  foot.geometry.translate(0, -0.44, 0.06);
  foot.castShadow = true;
  knee.add(foot);
  figure.add(pivot);
  return { pivot, knee };
}
const legL = makeLeg(1);
const legR = makeLeg(-1);

// ---- Animation state machine ----
const CYCLE = 10; // 0-2 stand, 2-5 walk, 5-8 run, 8-10 stand
const clock = new THREE.Clock();

function animateLimbPhase(t, speed, amp, phase, elbowAmp, kneeAmp, lean) {
  const s = Math.sin(t * speed + phase);
  const c = Math.cos(t * speed + phase);
  // legs
  legL.pivot.rotation.x = s * amp;
  legR.pivot.rotation.x = -s * amp;
  legL.knee.rotation.x = Math.max(0, -Math.cos(t * speed + phase + 0.5)) * kneeAmp;
  legR.knee.rotation.x = Math.max(0, -Math.cos(t * speed + phase + Math.PI + 0.5)) * kneeAmp;
  // arms opposite to legs
  armL.pivot.rotation.x = -s * amp * 0.9;
  armR.pivot.rotation.x = s * amp * 0.9;
  armL.elbow.rotation.x = -elbowAmp - Math.max(0, -s) * elbowAmp * 0.5;
  armR.elbow.rotation.x = -elbowAmp - Math.max(0, s) * elbowAmp * 0.5;
  // body
  torso.rotation.x = lean;
  const bob = Math.abs(Math.sin(t * speed)) * (amp * 0.12);
  figure.position.y = bob;
  figure.position.z = s * (amp * 0.05);
  headPivot.rotation.x = -lean * 0.6;
}

function resetPose() {
  legL.pivot.rotation.x = 0; legR.pivot.rotation.x = 0;
  legL.knee.rotation.x = 0; legR.knee.rotation.x = 0;
  armL.pivot.rotation.x = 0; armR.pivot.rotation.x = 0;
  armL.elbow.rotation.x = 0; armR.elbow.rotation.x = 0;
  torso.rotation.x = 0;
  figure.position.y = 0; figure.position.z = 0;
  headPivot.rotation.x = 0;
}

let beltSpeed = 0;

function tick() {
  const t = clock.getElapsedTime() % CYCLE;

  if (t < 2) {
    // STAND: subtle idle breathing
    resetPose();
    const b = Math.sin(t * 2.0) * 0.012;
    figure.position.y = b;
    armL.pivot.rotation.x = b * 2; armR.pivot.rotation.x = -b * 2;
    armL.elbow.rotation.x = -0.08; armR.elbow.rotation.x = -0.08;
    beltSpeed = 0;
  } else if (t < 5) {
    // WALK
    const wt = t - 2;
    animateLimbPhase(wt, 6.0, 0.55, 0, 0.35, 0.9, 0.03);
    beltSpeed = 1.2;
  } else if (t < 8) {
    // RUN
    const rt = t - 5;
    animateLimbPhase(rt, 11.0, 1.05, 0, 1.5, 1.9, 0.22);
    beltSpeed = 4.0;
  } else {
    // STAND again (with brief settle from run)
    resetPose();
    const st = t - 8;
    const settle = Math.max(0, 1 - st * 3);
    torso.rotation.x = 0.22 * settle * settle;
    figure.position.y = Math.sin(st * 6) * 0.03 * settle;
    armL.elbow.rotation.x = -0.08; armR.elbow.rotation.x = -0.08;
    beltSpeed = 4.0 * settle * settle;
  }

  // belt stripes scroll
  for (const s of stripes) {
    s.position.z -= beltSpeed * 0.016;
    if (s.position.z < -4.5) s.position.z += 9.8;
  }

  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}
tick();

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
